    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a1, uint a2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a1) + (a2)); require(a1 <= 1000000000000000000000000000000); require(a2 <= 1000000000000000000000000000000);
        require(a1 <= 1 ether && a2 <= 1 ether);
        require(address(this).balance >= a1);
        c.addToBalance{value: a1}(); if (__ESBMC_reverted()) return;
        uint b1 = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        require(address(this).balance >= a2);
        c.addToBalance{value: a2}(); if (__ESBMC_reverted()) return;
        uint b2 = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        assert(b2 >= b1);
    }
    receive() external payable {}
